package com.sixbean.testpike.core.requirement.api.dto;

import java.time.LocalDateTime;

/**
 *
 * @param version optimistic-lock anchor (V329): seeded 1 at create,
 * bumped on every real change; stale writes are refused 40901
 * @param sourceAnchor evidence anchor persisted at adoption :
 * null for manual points and legacy rows, so the
 * generation chain injects nothing and keeps its
 * byte-for-byte legacy prompt
 * @param fingerprint replay-stable content fingerprint :
 * generated by the database from doc attribution +
 * normalized title/acceptance-criteria, never
 * app-written; shown on both requirement lists
 */
public record RequirementInfo(Long id, Long projectId, Integer source, String sourceId,
                              String title, String acceptanceCriteria, Integer status,
                              String chapter, Long createdBy, LocalDateTime createdAt,
                              LocalDateTime updatedAt, Integer version,
                              RequirementSourceAnchor sourceAnchor, String fingerprint) {

    /** Pre- thirteen-arg shape (fingerprint not loaded): call sites keep compiling. */
    public RequirementInfo(Long id, Long projectId, Integer source, String sourceId,
                           String title, String acceptanceCriteria, Integer status,
                           String chapter, Long createdBy, LocalDateTime createdAt,
                           LocalDateTime updatedAt, Integer version,
                           RequirementSourceAnchor sourceAnchor) {
        this(id, projectId, source, sourceId, title, acceptanceCriteria, status, chapter,
                createdBy, createdAt, updatedAt, version, sourceAnchor, null);
    }

    /** Pre- twelve-arg shape (anchor not loaded): call sites keep compiling. */
    public RequirementInfo(Long id, Long projectId, Integer source, String sourceId,
                           String title, String acceptanceCriteria, Integer status,
                           String chapter, Long createdBy, LocalDateTime createdAt,
                           LocalDateTime updatedAt, Integer version) {
        this(id, projectId, source, sourceId, title, acceptanceCriteria, status, chapter,
                createdBy, createdAt, updatedAt, version, null, null);
    }
}
